# -*- coding: utf-8 -*-
from author_common import *
def mc(doc,page,prompt,a,b,c,e,why,level='understand'):
 add(doc,page,'single_choice',prompt,'a',why,[a,b,c,e]);q=qs[-1];q['id']=f'{doc}-x{sum(x["topic"]==doc for x in qs):02}';q['author_id']='question-engineer-b';q['cognitive_level']=level
d='p2-t4-d05'
mc(d,3,'GPS tạm mất trong hầm nhưng motion sensors còn hoạt động. Bộ lọc duy trì vị trí theo cách nào?','Tiếp tục prediction/dead reckoning rồi sửa lại khi GPS trở về','Giữ covariance cố định vì không có measurement mới','Coi tọa độ GPS cuối là phép đo mới ở mọi bước','Reset vị trí về gốc tọa độ mỗi khi GPS mất','Prediction mang state đi theo chuyển động trong lúc thiếu GPS; measurement trở lại giúp sửa drift.','apply')
mc(d,5,'Fusion gyro và accelerometer cho attitude khai thác sự bổ sung nào?','Gyro theo chuyển động nhanh tốt nhưng drift; accelerometer giúp kéo drift về','Cả hai đều không drift và không nhiễu nên chỉ lấy trung bình tùy ý','Accelerometer tích lũy drift quay còn gyro đo hướng trọng lực tuyệt đối','Chỉ cần gyro rồi bỏ mọi nguồn tham chiếu dài hạn','Hai nguồn có đặc tính lỗi khác nhau: gyro mượt ngắn hạn, gravity reference từ accelerometer hữu ích dài hạn.')
mc(d,7,'Ensemble Kalman filter xử lý covariance quá lớn để lưu trực tiếp bằng cách nào?','Ước lượng covariance từ độ phân tán của nhiều lần chạy mô hình','Đặt mọi covariance bằng 0 để không cần lưu','Chỉ giữ một trajectory rồi coi nó chứa mọi uncertainty','Bỏ observation update vì state dimension lớn','EnKF dùng ensemble samples biểu diễn spread thay lưu trực tiếp ma trận covariance khổng lồ.')
mc(d,14,'Trong Gaussian belief một chiều, độ lệch chuẩn lớn hơn thể hiện điều gì?','Belief rộng hơn và kém chắc chắn hơn','Trung bình bắt buộc tăng cùng độ lệch chuẩn','Belief hẹp hơn vì nhiều thông tin hơn','Sensor nhất thiết có bias dương','Mean biểu diễn vị trí ước lượng; spread biểu diễn uncertainty, không xác định chiều bias.')
mc(d,15,'Hai Gaussian beliefs độc lập cùng mô tả một đại lượng được fusion. Mean kết hợp nghiêng về phía nào?','Nguồn có variance nhỏ hơn','Nguồn có variance lớn hơn vì nó phủ nhiều giá trị','Luôn trung bình số học bất kể variance','Luôn chọn nguồn có mean lớn hơn','Inverse-variance weighting trao trọng số cao hơn cho nguồn chắc chắn hơn; giả định độc lập rất quan trọng.')
mc(d,17,'Trong Kalman update một chiều, innovation là gì?','Measurement trừ prediction của measurement','Covariance sau update trừ covariance trước predict','Tổng Q và R không phụ thuộc giá trị đo','Learning rate nhân state hiện tại','Innovation là độ bất ngờ của dữ liệu đo so với điều mô hình dự đoán.')
mc(d,17,'K gần 1 trong scalar Kalman update cho biết ước lượng mới có xu hướng nào?','Dịch mạnh về phía measurement','Giữ gần như nguyên prediction và bỏ measurement','Đảo innovation để đi xa measurement','Reset cả state và covariance về 0','Gain lớn trao trọng số lớn cho innovation; measurement đáng tin hơn prediction thì correction mạnh.')
mc(d,19,'Khi predict qua một bước có process noise, vì sao covariance cần tăng?','Có chuyển động/nhiễu chưa được mô hình hóa làm uncertainty tích lũy','Không có measurement mới thì uncertainty phải tự giảm','Prediction luôn chính xác hơn measurement nên covariance về 0','Q chỉ đổi mean và không liên quan covariance','Process noise biểu diễn phần thế giới không được motion model dự đoán chính xác; prediction cộng thêm uncertainty.')
mc(d,23,'Giữ prediction uncertainty cố định nhưng tăng R, bộ lọc sẽ tin measurement như thế nào?','Ít hơn vì measurement noise lớn hơn','Nhiều hơn vì R lớn chứng minh sensor mạnh','Không đổi vì R không tham gia gain','Loại toàn bộ motion model ở mọi bước','R lớn làm measurement kém chắc chắn và gain nhỏ hơn, nên correction dựa measurement yếu đi.')
mc(d,25,'Bộ lọc đo vị trí qua nhiều thời điểm có thể suy ra velocity dù sensor không đo trực tiếp nhờ đâu?','Motion model và quan hệ giữa sai số position/velocity trong state','Chỉ đổi tên measurement position thành velocity','Đặt velocity bằng 0 mãi vì không có sensor velocity','Chỉ dùng nhãn class của vật để chọn vận tốc cố định','State có thể chứa hidden quantities; chuỗi vị trí cùng dynamics và covariance coupling cho phép ước lượng velocity.')
mc(d,27,'Phần tử ngoài đường chéo covariance mô tả gì?','Quan hệ giữa sai số của các thành phần state','Chỉ variance riêng của một thành phần state','Giá trị mean của sensor đang dùng','Số measurement đã update trong lịch sử','Diagonal chứa uncertainty từng biến; off-diagonal chứa covariance/correlation giữa các biến.')
mc(d,32,'UKF truyền Gaussian belief qua hàm phi tuyến bằng đại diện nào?','Các sigma points rồi dựng lại mean/covariance có trọng số','Chỉ tiếp tuyến Jacobian tại mean như EKF','Một hạt duy nhất đặt tại mode và bỏ mọi spread','Toàn bộ lịch sử raw measurements không có state','UKF đẩy tập điểm đại diện qua hàm thật, không cần Jacobian nhưng vẫn biểu diễn Gaussian.')
mc(d,33,'Robot có thể đang ở một trong ba cửa giống nhau, belief có nhiều đỉnh. Vì sao particle filter phù hợp hơn Gaussian đơn?','Các particles có thể giữ nhiều giả thuyết vị trí riêng biệt','Một Gaussian đơn luôn giữ ba mode tách biệt chính xác','Particle filter bắt buộc gộp mọi mode thành một mean ngay','UKF luôn biến mọi multimodal belief thành đúng một vị trí thật','PF biểu diễn belief bằng weighted samples, có thể duy trì đa đỉnh khi robot chưa định vị rõ.')
mc(d,33,'Resampling trong particle filter có tác dụng gì với các particles sau measurement weighting?','Nhân các giả thuyết trọng số cao và loại bớt trọng số thấp','Giữ mọi particle đúng một bản bất kể likelihood','Chỉ dịch mọi particle cùng một khoảng mà không dùng weights','Gán mọi particle trọng số theo ID chẵn/lẻ','Resampling tập trung biểu diễn vào vùng có likelihood cao, bên cạnh bước motion và weighting.')
mc(d,37,'Track-to-track fusion cần lưu ý gì khi hai trackers dùng chung nguồn thông tin?','Errors có thể tương quan nên không thể coi hai track là độc lập tùy tiện','Hai tracker riêng process thì mọi error chắc chắn độc lập','Track estimates luôn chính xác hơn raw measurements bất kể nguồn chung','Gộp hai covariance bằng trung bình luôn tránh overconfidence','Nguồn sai số chung làm fusion ngây thơ đếm trùng thông tin và đánh giá uncertainty quá thấp.')
mc(d,38,'Measurement outlier kéo state nhảy mạnh. Gating nên dựa trên điều gì?','Innovation so với mức bất ngờ kỳ vọng và uncertainty','Chỉ giá trị tuyệt đối của measurement không xét prediction','Chỉ tên sensor mà bỏ residual của lần đo','Chỉ thứ tự measurement đến trong queue','Gating loại residual bất thường so với innovation covariance, tránh outlier được tin như measurement bình thường.')
d='p2-t4-d06'
mc(d,4,'Detector train trên scans đã deskew nhưng inference nhận scans méo khi xe quay. Đây là loại mismatch nào?','Preprocessing train/inference không nhất quán','Chỉ class imbalance giữa xe và người','Chỉ head có ít output channels','Chỉ score threshold cao hơn mặc định','Deskew là phần input contract; khác preprocessing gây distribution mismatch dù model weights đúng.','analyze')
mc(d,5,'Point attributes có time offset ngoài xyz hữu ích cho tác vụ tiền xử lý nào?','Bù chuyển động trong thời gian scan','Đổi trực tiếp class label mà không có học','Tạo camera focal length thay calibration','Thay mọi point coordinates bằng row index','Các points không nhất thiết đo cùng thời điểm; time offsets cùng motion/pose hỗ trợ deskew.')
mc(d,8,'PointNet gốc hạn chế gì khi cần khai thác cấu trúc lân cận trong cảnh lớn?','Local structure yếu và khó scale lên toàn cảnh','Bắt buộc voxel hóa trước nên không còn point-level input','Chỉ dùng được ảnh màu có lưới đều','Không thể dùng như object refinement module','PointNet thuận trực tiếp trên tập điểm nhưng local geometry và scale scene là hạn chế; có thể dùng như building block.')
mc(d,9,'Voxel size cần được coi là hyperparameter hệ thống vì tác động đồng thời đến điều gì?','Độ chi tiết hình học, mAP, memory và latency','Chỉ số class, không ảnh hưởng compute','Chỉ màu hiển thị point cloud','Chỉ tên coordinate frame mà không thay dữ liệu','Discretization resolution điều chỉnh mức chi tiết và lượng ô cần xử lý; cần đo cả quality lẫn budget.')
mc(d,9,'Point cloud range quá hẹp gây mất recall theo cơ chế nào?','Points của object ngoài vùng crop bị loại trước detector','Object ngoài range vẫn luôn được backbone suy lại chính xác','Chỉ giảm số class, không thay coverage không gian','Chỉ tăng memory chứ không bỏ bất kỳ points nào','Range filter xác định phần không gian đầu vào; model không thể dùng points đã bị crop ra.')
mc(d,9,'Muốn tái lập benchmark voxel detector cần giữ rõ cấu hình nào ngoài model name?','Voxel size, cloud range, max points/voxel và max voxels','Chỉ số epoch mà bỏ mọi voxelization config','Chỉ random seed, mọi input representation đều tương đương','Chỉ checkpoint filename vì preprocessing tự được suy ra','Giới hạn voxelization quyết định dữ liệu thực vào backbone và compute, nên là một phần benchmark contract.')
mc(d,10,'Robot cần phân biệt vật cản cao và thấp chồng lên nhau. Pillar/BEV có đánh đổi cần xem xét nào?','Nén chiều cao sớm có thể làm mất chi tiết theo trục đứng','Pillar luôn giữ nguyên mọi chi tiết z ở mọi layer','BEV tự tạo đủ depth cho mọi vật bị che','Pillar chỉ có vấn đề class names, không liên quan hình học','Pseudo-image BEV hiệu quả nhưng mất chi tiết chiều cao sớm, khó hơn với vật chồng lớp.')
mc(d,11,'Port 3D boxes giữa hai datasets cần kiểm convention nào để tránh box sai hình dù tensor shape đúng?','Thứ tự w/l/h, mốc tâm và chiều yaw/trục tọa độ','Chỉ số lượng class có cùng length','Chỉ tên split train/validation','Chỉ số points còn sau crop','Datasets có thể khác axis, heading, center convention; shape đúng không chứng minh semantics đúng.')
mc(d,12,'Center-based 3D detection head dự đoán gì sau khi định vị tâm object?','Kích thước, hướng và có thể velocity','Chỉ anchor ID rồi giữ nguyên kích thước mọi object','Chỉ camera RGB class score không có geometry','Chỉ IoU giữa hai ground truth boxes','Center-based heads dùng center làm điểm tham chiếu rồi regress thuộc tính hộp/động học.')
mc(d,13,'3D detector có false positives gần đầu xe dù mAP tổng tăng. Vì sao cần đánh giá riêng vùng này?','Planner có thể nhạy với obstacle giả trong vùng chuyển động','Mọi false positive ở mọi nơi đều có cùng tác động điều khiển','mAP cao tự bảo đảm planner tốt hơn','Chỉ latency quyết định tác động, vị trí false positive không quan trọng','Metric tổng không biểu diễn đầy đủ risk không gian; vùng gần ego/planner cần theo dõi lỗi riêng.')
mc(d,19,'Feature fusion khác early fusion ở điểm ghép hai modalities nào?','Mỗi sensor học feature riêng rồi mới kết hợp','Ghép raw inputs trước mọi feature extraction','Chỉ ghép final tracks sau khi mọi detector hoàn tất','Không trao đổi bất kỳ thông tin nào giữa sensors','Early ghép input; mid/feature fusion ghép đặc trưng; late ghép output của module độc lập.')
mc(d,20,'Frustum PointNets dùng detection 2D để giới hạn xử lý 3D bằng cách nào?','Sinh frustum và lấy points nằm trong vùng đó để ước lượng box 3D','Đổi mọi pixel box thành point có depth cố định duy nhất','Chỉ gộp final 2D boxes mà không dùng point cloud','Voxel hóa toàn cảnh rồi bỏ mọi thông tin 2D','Box ảnh tạo vùng frustum trong không gian, giúp chọn cụm points cho bước 3D.')
mc(d,20,'PointPainting đưa tri thức camera vào LiDAR ở dạng nào?','Gắn semantic score của pixel tương ứng vào point','Chỉ tô màu viewer mà không thêm feature cho points','Dùng camera exposure làm ground truth yaw','Thay xyz point bằng normalized box coordinates','Camera segmentation/detection cung cấp semantic scores gắn qua phép chiếu cho từng point.')
mc(d,20,'BEVFusion đưa camera và LiDAR về không gian chung nào để kết hợp feature?','Bird’s-eye-view','Raw RGB pixel grid duy nhất mà không dùng geometry','Danh sách class names không có tọa độ','Chuỗi timestamps thay thế feature maps','Unified BEV cho phép kết hợp representation của hai modalities trong một không gian nhìn từ trên xuống.')
mc(d,21,'Box 3D khớp point cloud nhưng overlay lên ảnh sai, bước điều tra nào sát hơn thay head detector?','Kiểm phép chiếu và calibration giữa LiDAR/camera','Chỉ tăng regression loss weight của box','Chỉ thêm nhiều object queries cho head','Chỉ tăng số anchors theo hướng yaw','Geometry đúng trong point cloud nhưng sai khi chiếu gợi ý projection/calibration bug hơn lỗi detector.','analyze')
mc(d,23,'Chọn pipeline 3D cho drone thay vì xe chạy chủ yếu trên mặt phẳng cần xét khác biệt nào?','Motion 6-DoF/quay mạnh cùng hạn chế power và compute','Coi mọi chuyển động đều planar và dùng nguyên budget của xe','Bỏ motion robustness vì drone luôn ít rung','Chỉ tăng far-range car recall mà bỏ vật cản và chuyển động drone','Platform khác đổi motion, sensor setup và resource constraints; pipeline cần đánh giá robustness phù hợp.')
